use super::*;

/// The `promote` argv this tool delegates — the harvested ids, and NOTHING else.
///
/// A FUNCTION for the same reason [`impl_set_argv`] is one: `delegate` is a free function no test can
/// capture, so the only way to pin what is SENT is to build the argv somewhere a test can read it.
///
/// `--id` is the whole guard. A bare `bsc graph promote` refreshes EVERY tracked record from the
/// shared runtime store, which every session on the box is authoring into at once — so a migration
/// that promoted bare would sweep other people's in-flight records into this branch's
/// `graph/algorithms.json` and say nothing about it. It is invisible from the tool's output and from a
/// line count; only a parsed diff by record id against the base commit shows it.
pub(crate) fn promote_argv(ids: &[String], root: &Path) -> Vec<String> {
    ["promote", "--id", &ids.join(","), "--root", &root.to_string_lossy()]
        .iter()
        .map(|s| (*s).to_string())
        .collect()
}
